import React from "react";
import { Calendar } from "primereact/calendar"; // Assuming you are using PrimeReact's Calendar
import { Tooltip } from "primereact/tooltip"; // For tooltip on appointments
import "./css/calendar.css"; // Create a separate CSS for styling

const AppointmentsCalendar = ({ appointments }) => {
  const appointmentStyle = (status) => {
    switch (status) {
      case "completed":
        return { backgroundColor: "green", color: "white" };
      case "pending":
        return { backgroundColor: "yellow", color: "black" };
      case "confirmed":
        return { backgroundColor: "blue", color: "white" };
      case "cancelled":
        return { backgroundColor: "red", color: "white" };
      default:
        return {};
    }
  };

  return (
    <div>
      <Calendar
        dateFormat="mm/dd/yy"
        // Other calendar properties
        onChange={(e) => setSelectedDate(e.value)} // Implement state for the selected date
        inline
        monthNavigator
        yearNavigator
      />
      <div className="appointment-list">
        {appointments.map((appointment) => (
          <div 
            key={appointment._id} 
            style={appointmentStyle(appointment.status)} 
            className="appointment-item"
            data-pr-tooltip={`Pet: ${appointment.pet_id.name}\nReason: ${appointment.notes}\nVet: ${appointment.vet_id.name}`} // Tooltip for appointment details
          >
            {format(new Date(appointment.date), 'MMMM dd, yyyy')}
          </div>
        ))}
      </div>
      <Tooltip />
    </div>
  );
};

export default AppointmentsCalendar;
